package com.mediroute.service;
import com.mediroute.entity.*; import com.mediroute.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.messaging.simp.SimpMessagingTemplate; import java.util.*;
@Service public class DispatchService {
private final AmbulanceRepository ambulances; private final HospitalRepository hospitals; private final EmergencyRepository emergencies; private final SimpMessagingTemplate ws; private final RouteService routes;
public DispatchService(AmbulanceRepository a,HospitalRepository h,EmergencyRepository e,SimpMessagingTemplate ws,RouteService routes){this.ambulances=a;this.hospitals=h;this.emergencies=e;this.ws=ws;this.routes=routes;}
@Transactional public Emergency create(String name,String contact,double lat,double lon){Emergency e=emergencies.save(new Emergency(name,contact,lat,lon)); GeoPoint p=new GeoPoint(lat,lon); Ambulance best=ambulances.findByStatus(Ambulance.Status.AVAILABLE).stream().filter(a->a.getLatitude()!=null&&a.getLongitude()!=null).min(Comparator.comparingDouble(a->p.distanceKm(new GeoPoint(a.getLatitude(),a.getLongitude())))).orElseThrow(()->new IllegalStateException("No available ambulance with a reported location")); best.assign();e.assign(best); emergencies.save(e);ambulances.save(best);publish(e);return e;}
@Transactional public Emergency assess(long id,String symptoms,String capability){Emergency e=emergencies.findById(id).orElseThrow();e.assess(symptoms,capability); Hospital h=hospitals.findAll().stream().filter(Hospital::isActive).filter(x->x.getAvailableBeds()>0).filter(x->capability==null||capability.isBlank()||x.getCapabilities().stream().anyMatch(c->c.equalsIgnoreCase(capability))).min(Comparator.comparingDouble(x->new GeoPoint(e.getPickupLat(),e.getPickupLon()).distanceKm(new GeoPoint(x.getLatitude(),x.getLongitude())))).orElseThrow(()->new IllegalStateException("No active hospital with matching capability and available beds")); e.selectHospital(h);publish(e);return emergencies.save(e);}
public List<com.mediroute.route.RouteCandidate> routes(long id){Emergency e=emergencies.findById(id).orElseThrow(); if(e.getHospital()==null)throw new IllegalStateException("Hospital not selected"); return routes.alternatives(e.getPickupLat(),e.getPickupLon(),e.getHospital().getLatitude(),e.getHospital().getLongitude());}
@Transactional public Emergency setStatus(long id,String status){Emergency e=emergencies.findById(id).orElseThrow();e.updateStatus(status);if("COMPLETED".equalsIgnoreCase(status)&&e.getAmbulance()!=null){e.getAmbulance().release();ambulances.save(e.getAmbulance());}publish(e);return emergencies.save(e);}
@Transactional public Emergency chooseHospital(long id,long hospitalId){Emergency e=emergencies.findById(id).orElseThrow();Hospital h=hospitals.findById(hospitalId).orElseThrow();e.selectHospital(h);publish(e);return emergencies.save(e);}
@Transactional public Ambulance locate(long id,double lat,double lon){Ambulance a=ambulances.findById(id).orElseThrow();a.updateLocation(lat,lon);ambulances.save(a);ws.convertAndSend("/topic/ambulances/"+id,Map.of("id",id,"lat",lat,"lon",lon));return a;}
@Transactional public Ambulance locateUnit(String unitCode,double lat,double lon){Ambulance a=ambulances.findByUnitCodeIgnoreCase(unitCode).orElseThrow();a.reportCrewLocation(lat,lon);ambulances.save(a);ws.convertAndSend("/topic/ambulances/"+a.getId(),Map.of("id",a.getId(),"lat",lat,"lon",lon));return a;}
private void publish(Emergency e){ws.convertAndSend("/topic/emergencies/"+e.getId(),Map.of("id",e.getId(),"status",e.getStatus(),"ambulanceId",e.getAmbulance()==null?-1:e.getAmbulance().getId(),"hospitalId",e.getHospital()==null?-1:e.getHospital().getId()));}
}
